private fun materialSymbol(name: String, pathData: String): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 960f, viewportHeight = 960f)
        .group(translationY = 960f) { addPath(pathData = PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(Color.Black)) }
        .build()
